import json, numpy as np
m=json.load(open('/app/output/view_obs/meta.json'))
for c in ('ego','wrist_right'):
 d=m['cameras'][c]; K=np.array(d['intrinsic_cv']); E=np.array(d['extrinsic_cv']); R=E[:,:3]; t=E[:,3]; C=-R.T@t
 print('\n',c,'cam',C)
 for uv in ([(290,277),(267,251),(327,302),(408,289),(410,292)] if c=='ego' else [(408,290),(410,290),(83,197),(218,351),(150,270)]):
  rayw=R.T@np.linalg.inv(K)@np.array([uv[0],uv[1],1.])
  for z in ([.76] if c=='ego' else [.76,.80,.82]):
   a=(z-C[2])/rayw[2]; p=C+a*rayw
   if z==.76: print(uv, '->',p.round(4))
   elif uv in [(408,290),(410,290)]: print(' ',z,p.round(4))
PY

